/**
 * Translations beyond the built-in French and English.
 *
 * Every module registers its text tables (`{ fr, en }`). Languages other than French fall
 * back to English; for them, `plugin/locales/client/<lang>.json` (served by
 * ajax/i18n.php for the user's GLPI language) overlays the English tables at startup:
 * translators add a JSON file, no rebuild.
 *
 * In the JSON, texts that take values use `{0}`, `{1}`… in the order of the English
 * function's parameters (see plugin/locales/client-template.json, generated by
 * `npm run i18n-template`).
 */

type Table = Record<string, unknown>;

const tables = new Map<string, { en: Table }>();

export function register<T>(ns: string, t: T): T {
  tables.set(ns, t as unknown as { en: Table });
  return t;
}

/** `"{0} a modifié {1}"` → `(a, b) => …`, for texts that are functions in English. */
function templated(s: string): (...args: unknown[]) => string {
  return (...args) => s.replace(/\{(\d+)\}/g, (_, i) => String(args[Number(i)] ?? ""));
}

function overlay(base: Table, extra: unknown): void {
  if (!extra || typeof extra !== "object") return;
  for (const [k, v] of Object.entries(extra as Table)) {
    const cur = base[k];
    if (typeof cur === "function" && typeof v === "string") base[k] = templated(v);
    else if (typeof cur === "string" && typeof v === "string") base[k] = v;
    else if (Array.isArray(cur) && Array.isArray(v)) base[k] = v.map(String);
    else if (cur && typeof cur === "object" && !Array.isArray(cur)) overlay(cur as Table, v);
  }
}

/** Applies a catalog `{ namespace: { key: text } }` over the English tables. */
export function applyCatalog(catalog: unknown): void {
  if (!catalog || typeof catalog !== "object") return;
  for (const [ns, extra] of Object.entries(catalog as Table)) {
    const t = tables.get(ns);
    if (t) overlay(t.en, extra);
  }
}

/** The English tables as a catalog template: functions become `{0}`… texts. */
export function template(): Record<string, unknown> {
  const dump = (v: unknown): unknown => {
    if (typeof v === "function") return v(...Array.from({ length: v.length }, (_, i) => `{${i}}`));
    if (Array.isArray(v)) return v.slice();
    if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, dump(x)]));
    return v;
  };
  return Object.fromEntries([...tables].sort(([a], [b]) => a.localeCompare(b)).map(([ns, t]) => [ns, dump(t.en)]));
}

/** French and English are built in; other languages need a catalog. */
export function needsCatalog(lang: string): boolean {
  const code = lang.slice(0, 2).toLowerCase();
  return code !== "fr" && code !== "en" && code !== "";
}
